const e=$('TRG - Receber Dados WF006').first().json;
const lista=$items('GS - Buscar Agendamentos Ativos').map(i=>i.json).filter(x=>x&&x.ID_AGENDAMENTO);
const clientePorTelefone=$('GS - Buscar Cliente por Telefone').first().json;

function mesmoDia(raw,alvo){
  if(!raw||!alvo) return false;
  const parse=v=>{
    let dt=DateTime.fromFormat(String(v),'dd/MM/yyyy');
    if(!dt.isValid) dt=DateTime.fromFormat(String(v),'yyyy-MM-dd');
    if(!dt.isValid) dt=DateTime.fromISO(String(v));
    return dt;
  };
  const a=parse(raw), b=parse(alvo);
  return a.isValid&&b.isValid&&a.hasSame(b,'day');
}

const base={
  id_empresa:e.id_empresa||'EMP001',
  id_cliente:e.id_cliente||'',
  telefone_cliente:e.telefone_cliente||'',
  nome_cliente:e.nome_cliente||'Cliente',
  origem:e.origem||'WHATSAPP',
  phone_number_id:e.phone_number_id||'',
  mensagem_texto:e.mensagem_texto||'',
  intencao:e.intencao||'',
  confianca:e.confianca,
  dados:e.dados||{},
  novo_hora_inicio:e.hora_inicio||'',
  novo_periodo:e.periodo||''
};

let candidatos=[];

if(e.id_agendamento){
  // prioridade absoluta: id_agendamento informado
  candidatos=lista.filter(a=>String(a.ID_AGENDAMENTO)===String(e.id_agendamento));
}else{
  const idClienteResolvido=e.id_cliente||(clientePorTelefone&&clientePorTelefone.ID_CLIENTE)||'';
  if(!idClienteResolvido){
    return [{json:{...base,encontrado:false,status:'NAO_ENCONTRADO',resposta_cliente:'Não encontrei nenhum agendamento ativo para reagendar. Pode confirmar os dados do agendamento?'}}];
  }
  candidatos=lista.filter(a=>String(a.ID_CLIENTE)===String(idClienteResolvido));

  // 'data' so e usada para desambiguar quando ha mais de 1 candidato: pode ser a data
  // do agendamento ATUAL (o que o cliente quer alterar) OU a data NOVA desejada;
  // por isso so filtra por data quando isso reduz para exatamente 1 candidato,
  // nunca aplica o filtro as cegas.
  if(candidatos.length>1&&e.data){
    const filtrados=candidatos.filter(a=>mesmoDia(a.DATA,e.data));
    if(filtrados.length===1) candidatos=filtrados;
  }
}

if(candidatos.length===0){
  return [{json:{...base,encontrado:false,status:'NAO_ENCONTRADO',resposta_cliente:'Não encontrei nenhum agendamento ativo para reagendar. Pode confirmar os dados do agendamento?'}}];
}

if(candidatos.length>1){
  const opcoes=candidatos.slice(0,6).map(a=>`${a.DATA} às ${String(a.HORA_INICIO||'').slice(0,5)}`).join('; ');
  return [{json:{...base,encontrado:false,status:'MULTIPLOS_AGENDAMENTOS',resposta_cliente:`Encontrei mais de um agendamento ativo: ${opcoes}. Pode me dizer qual deles você quer reagendar (data e horário atuais)?`}}];
}

const a=candidatos[0];
return [{json:{...base,encontrado:true,status:'ENCONTRADO',
  id_agendamento:a.ID_AGENDAMENTO,
  id_cliente:a.ID_CLIENTE||base.id_cliente,
  id_profissional_atual:a.ID_PROFISSIONAL||'',
  id_servico:a.ID_SERVICO||'',
  servico:a.ID_SERVICO||'',
  data_atual:a.DATA,
  hora_inicio_atual:String(a.HORA_INICIO||'').slice(0,5),
  duracao_min_atual:Number(a.DURACAO_MIN||60),
  google_event_id:a.GOOGLE_EVENT_ID||'',
  data_nova:e.data||a.DATA,
  resposta_cliente:''
}}];

const a=$('CODE - Localizar Agendamento').first().json;
const emp=$('GS - Buscar Empresa').first().json;

function parseDataHora(dataStr,horaStr){
  let dt=DateTime.fromFormat(`${dataStr} ${horaStr}`,'dd/MM/yyyy HH:mm');
  if(!dt.isValid) dt=DateTime.fromFormat(`${dataStr} ${horaStr}`,'yyyy-MM-dd HH:mm');
  if(!dt.isValid) dt=DateTime.fromISO(`${dataStr}T${horaStr}`);
  return dt;
}

const inicio=parseDataHora(a.data_atual,String(a.hora_inicio_atual||'00:00').slice(0,5));
const agora=DateTime.now();
const minutosAte=inicio.isValid?inicio.diff(agora,'minutes').minutes:null;
const prazoMin=Number((emp&&emp.TEMPO_CANCELAMENTO_MIN)||0);

const dentroDoPrazo=minutosAte!==null&&minutosAte>=prazoMin;

if(!dentroDoPrazo){
  return [{json:{...a,dentro_do_prazo:false,status:'FORA_PRAZO_REAGENDAMENTO',minutos_ate_agendamento:minutosAte,resposta_cliente:`Infelizmente não é possível reagendar automaticamente esse atendimento porque estamos fora do prazo de ${prazoMin} minutos de antecedência. Entre em contato com a equipe para verificar a possibilidade de reagendamento.`}}];
}

return [{json:{...a,dentro_do_prazo:true,status:'DENTRO_DO_PRAZO',minutos_ate_agendamento:minutosAte}}];

const loc=$('CODE - Validar Prazo').first().json;
const d=$('EXEC - WF004 - Consultar Nova Disponibilidade').first().json;

const horarios=Array.isArray(d.horarios)?d.horarios:[];

const tm=t=>{const [h,m]=String(t||'00:00').slice(0,5).split(':').map(Number);return h*60+m};
const hs=m=>String(Math.floor(m/60)).padStart(2,'0')+':'+String(m%60).padStart(2,'0');

if(d.status!=='OK'||horarios.length===0){
  return [{json:{...loc,horario_valido:false,status:'SEM_DISPONIBILIDADE',resposta_cliente:d.resposta_cliente||'Não encontrei horários disponíveis para o novo agendamento. Podemos tentar outra data ou horário?'}}];
}

let horaEscolhida=null;
if(loc.novo_hora_inicio){
  const alvo=String(loc.novo_hora_inicio).slice(0,5);
  horaEscolhida=horarios.find(h=>h===alvo)||null;
  if(!horaEscolhida){
    return [{json:{...loc,horario_valido:false,status:'HORARIO_INDISPONIVEL',resposta_cliente:`O horário ${alvo} não está disponível para o novo agendamento. Horários livres: ${horarios.slice(0,6).join(', ')}. Qual prefere?`}}];
  }
}else{
  horaEscolhida=horarios[0]; // escolha determinística: primeiro horário livre da lista (já filtrada por periodo pelo WF004)
}

const duracaoMin=Number(d.duracao_min||loc.duracao_min_atual||60);
const horaFimNova=hs(tm(horaEscolhida)+duracaoMin);

return [{json:{...loc,horario_valido:true,status:'NOVO_HORARIO_OK',
  data_nova:d.data,
  hora_inicio_nova:horaEscolhida,
  hora_fim_nova:horaFimNova,
  duracao_min:duracaoMin,
  id_profissional_novo:d.id_profissional||loc.id_profissional_atual||''
}}];
